    private static string Describe(AbstractStruct s)
    {
        if (s is not Item item)
        {
            return s.GetType().Name + s.Id + ":" + s.Length;
        }
        var content = item.Content switch
        {
            ContentDeleted d => "Deleted(" + d.Length + ")",
            ContentString cs => "String(" + cs.Value + ")",
            ContentAny a     => "Any(" + JsJson.Stringify(a.GetContent()) + ")",
            ContentType t    => "Type(" + t.Value.GetType().Name + (t.Value is XmlElement e ? ":" + e.NodeName : string.Empty) + ")",
            _                => item.Content.GetType().Name,
        };
        return $"{item.Id} o:{item.OriginId} ro:{item.RightOriginId} p:{item.ParentKey ?? (item.ParentId?.ToString())} s:{item.Key} {content}";
    }

    private static void Roundtrip(byte[] payload, string[] expected, bool v2)
    {
        var (structs, _) = v2 ? Y.DecodeUpdateV2(payload) : Y.DecodeUpdate(payload);
        CollectionAssert.AreEqual(expected, structs.Select(Describe).ToArray(), v2 ? "failed to decode V2" : "failed to decode V1");
        var doc = new Doc();
        if (v2)
        {
            doc.ApplyUpdateV2(payload);
            CollectionAssert.AreEqual(payload, doc.EncodeStateAsUpdateV2(), "failed to encode V2");
        }
        else
        {
            doc.ApplyUpdate(payload);
            CollectionAssert.AreEqual(payload, doc.EncodeStateAsUpdate(), "failed to encode V1");
        }
    }

    // yrs: text_insert_delete
    [TestMethod]
    public void TextInsertDelete()
    {
        const ulong c = 264992024;
        var expected = new[]
        {
            $"<{c}#0> o: ro: p:type s: Deleted(3)",
            $"<{c}#3> o: ro:<{c}#0> p: s: String(ab)",
            $"<{c}#5> o:<{c}#4> ro:<{c}#0> p: s: Deleted(1)",
            $"<{c}#6> o:<{c}#2> ro: p: s: Deleted(1)",
            $"<{c}#7> o:<{c}#6> ro: p: s: String(hi)",
        };
        var visited = false;
        var doc     = new Doc();
        var txt     = doc.GetText("type");
        doc.Update += (_, e) =>
        {
            var (structs, ds) = Y.DecodeUpdate(e.Update);
            CollectionAssert.AreEqual(expected, structs.Select(Describe).ToArray());
            CollectionAssert.AreEqual(new[] { new DeleteItem(0, 3), new DeleteItem(5, 2) }, ds.Get(c).ToArray());
            visited = true;
        };
        doc.ApplyUpdate(text_insert_delete_update_0);
        Assert.AreEqual("abhi", txt.ToString());
        Assert.IsTrue(visited);
    }

