    // yrs: utf32_lib0_v2_decoding
    [TestMethod]
    public void Utf32Lib0V2Decoding()
    {
        var doc = new Doc();
        var xml = doc.GetXmlFragment("prosemirror");
        doc.ApplyUpdateV2(utf32_lib0_v2_decoding_data_0);
        var actual = (XmlElement)xml.Get(0)!;
        var attrs  = actual.GetAttributes();
        Assert.AreEqual(4, attrs.Count);
        Assert.AreEqual("JXbASa-a92j", attrs["b_id"]);
        JsonEqual(0, attrs["indent"]);
        Assert.AreEqual("div", attrs["tagName"]);
        Assert.AreEqual("", attrs["lineHeight"]);
        Assert.AreEqual("在の韩国🇰🇷🇨🇳🇯🇵", ((XmlText)actual.Get(0)!).ToString());
        // the payload was produced by an older encoder; Yjs 13.6.33 re-encodes it to exactly these bytes
        CollectionAssert.AreEqual(Utf32ReencodedByYjs, doc.EncodeStateAsUpdateV2());
    }

