    // yrs: negative_zero_decoding_v2
    [TestMethod]
    public void NegativeZeroDecodingV2()
    {
        var doc  = new Doc();
        var root = doc.GetMap("root");
        doc.Transact(_ =>
        {
            var sequence = root.Set("sequence", new YMap());
            sequence.Set("id", "V9Uk9pxUKZIrW6cOkC0Rg");
            sequence.Set("cuts", new YArray());
            sequence.Set("name", "new sequence");
            root.Set("__version__", 1);
            root.Set("face_expressions", new YArray());
            root.Set("characters", new YArray());
        });
        var expected = root.ToJson();
        var buffer   = doc.EncodeStateAsUpdateV2();
        var doc2     = new Doc();
        doc2.ApplyUpdateV2(buffer);
        JsonEqual(expected, doc2.GetMap("root").ToJson());
    }

    private static string AssetPath(string name) => Path.Combine(AppContext.BaseDirectory, "Core", "Assets", name);

    // yrs: test_small_data_set
    [TestMethod]
    public void SmallDataSet() => TestDataSet(AssetPath("small-test-dataset.bin"));

    // yrs: test_medium_data_set (31 MB, not committed: runs when the yrs assets are available locally)
    [TestMethod]
    public void MediumDataSet()
    {
        var path = Environment.GetEnvironmentVariable("YRS_ASSETS") is { } dir
            ? Path.Combine(dir, "bench-input", "medium-test-dataset.bin")
            : "/tmp/ycrdt/assets/bench-input/medium-test-dataset.bin";
        if (!File.Exists(path))
        {
            Assert.Inconclusive("medium-test-dataset.bin not available (set YRS_ASSETS to the y-crdt assets folder)");
        }
        TestDataSet(path);
    }

    private static void TestDataSet(string path)
    {
        var decoder   = new Decoder(File.ReadAllBytes(path));
        var testCount = decoder.ReadVarUInt();
        for (ulong testNum = 0; testNum < testCount; testNum++)
        {
            var updatesLen = decoder.ReadVarUInt();
            var doc        = new Doc();
            var txt        = doc.GetText("text");
            var map        = doc.GetMap("map");
            var arr        = doc.GetArray("array");
            for (ulong i = 0; i < updatesLen; i++)
            {
                doc.ApplyUpdate(decoder.ReadVarUInt8Array());
            }
            Assert.AreEqual(decoder.ReadVarString(), txt.ToString(), $"failed at {testNum} run");
            JsonEqual(decoder.ReadAny(), map.ToJson());
            JsonEqual(decoder.ReadAny(), arr.ToJson());
        }
    }

    // yrs: edit_trace_* (tests/edit_traces_tests.rs). Positions in the traces are Unicode code points.
    [TestMethod]
    public void EditTraceAutomerge() => TestEditingTrace("automerge-paper.json.gz");

    [TestMethod]
    public void EditTraceFriendsForever() => TestEditingTrace("friendsforever_flat.json.gz");

    [TestMethod]
    public void EditTraceSephBlog1() => TestEditingTrace("seph-blog1.json.gz");

    [TestMethod]
    public void EditTraceSvelteComponent() => TestEditingTrace("sveltecomponent.json.gz");

    [TestMethod]
    public void EditTraceRustCode() => TestEditingTrace("rustcode.json.gz");

    private static void TestEditingTrace(string name)
    {
        using var file = File.OpenRead(AssetPath(name));
        using var gz   = new GZipStream(file, CompressionMode.Decompress);
        using var json = System.Text.Json.JsonDocument.Parse(gz);
        var root = json.RootElement;
        // none of the traces uses byte positions or characters outside the BMP, so code points are UTF-16 indexes
        Assert.IsFalse(root.TryGetProperty("using_byte_positions", out var ubp) && ubp.GetBoolean());
        var doc   = new Doc();
        var txt   = doc.GetText("text");
        var start = root.GetProperty("startContent").GetString()!;
        if (start.Length > 0)
        {
            txt.Insert(0, start);
        }
        foreach (var t in root.GetProperty("txns").EnumerateArray())
        {
            doc.Transact(_ =>
            {
                foreach (var patch in t.GetProperty("patches").EnumerateArray())
                {
                    var at      = patch[0].GetInt32();
                    var delete  = patch[1].GetInt32();
                    var content = patch[2].GetString()!;
                    if (delete != 0)
                    {
                        txt.Delete(at, delete);
                    }
                    if (content.Length > 0)
                    {
                        Assert.IsFalse(content.Any(char.IsSurrogate));
                        txt.Insert(at, content);
                    }
                }
            });
        }
        Assert.AreEqual(root.GetProperty("endContent").GetString(), txt.ToString());
        var copy = new Doc();
        copy.ApplyUpdateV2(doc.EncodeStateAsUpdateV2());
        Assert.AreEqual(txt.ToString(), copy.GetText("text").ToString());
        var copyV1 = new Doc();
        copyV1.ApplyUpdate(doc.EncodeStateAsUpdate());
        Assert.AreEqual(txt.ToString(), copyV1.GetText("text").ToString());
    }
